# Builds the signed Windows release of Ember locally.
#
#   powershell -ExecutionPolicy Bypass -File scripts\build-release.ps1
#
# Reads the updater signing key from %USERPROFILE%\.tauri, builds through
# Tauri (NSIS + updater artifacts), and verifies that the installer, the
# updater payload and its signature all landed. CI uses the same key through
# repository secrets; `latest.json` is generated by tauri-action there.

$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$keyDir = Join-Path $env:USERPROFILE ".tauri"
$keyFile = Join-Path $keyDir "ember-updater.key"
$passwordFile = Join-Path $keyDir "ember-updater.key.password.txt"

if (-not (Test-Path $keyFile)) {
    throw "Updater key not found at $keyFile. Generate one with: npx tauri signer generate -w $keyFile"
}

$env:TAURI_SIGNING_PRIVATE_KEY = Get-Content -Raw $keyFile
if (Test-Path $passwordFile) {
    $env:TAURI_SIGNING_PRIVATE_KEY_PASSWORD = (Get-Content -Raw $passwordFile).Trim()
}

Write-Host "Building Ember (release, signed)..."
Push-Location $root
try {
    npm run tauri build
} finally {
    Pop-Location
}

$bundleDir = Join-Path $root "src-tauri\target\release\bundle\nsis"
$conf = Get-Content (Join-Path $root "src-tauri\tauri.conf.json") -Raw | ConvertFrom-Json
$version = $conf.version
$installer = Get-ChildItem $bundleDir -Filter "Ember_${version}_*setup.exe" -ErrorAction SilentlyContinue
$signature = Get-ChildItem $bundleDir -Filter "Ember_${version}_*setup.exe.sig" -ErrorAction SilentlyContinue

if (-not $installer) { throw "No $version installer was produced in $bundleDir" }
if (-not $signature) { throw "No update signature (*setup.exe.sig) was produced in $bundleDir" }

Write-Host ""
Write-Host "Release artifacts (for Ember v$version):"
Write-Host "  installer  : $($installer.FullName)"
Write-Host "               (also the updater payload installed copies download)"
Write-Host "  signature  : $($signature.FullName)"
Write-Host "  latest.json: generated by CI (tauri-action) and attached to the GitHub release"
